#include "ascii-sharded-frequency.h"

std::optional<std::unordered_map<char,std::size_t>> charm::v1n7::parallel_letter_frequency::sharded_ascii_frequency(const std::vector<std::string>& inputs,std::size_t worker_count){if(worker_count==0)return std::nullopt;if(inputs.empty())return std::unordered_map<char,std::size_t>{};std::size_t workers=std::min(worker_count,inputs.size());std::vector<std::future<std::unordered_map<char,std::size_t>>> jobs;for(std::size_t w=0;w<workers;++w)jobs.push_back(std::async(std::launch::async,[&,w]{std::unordered_map<char,std::size_t> local;for(std::size_t i=w;i<inputs.size();i+=workers)for(unsigned char c:inputs[i])if(c<128&&std::isalpha(c))++local[static_cast<char>(std::tolower(c))];return local;}));std::unordered_map<char,std::size_t> result;for(auto& job:jobs)for(const auto& item:job.get())result[item.first]+=item.second;return result;}
